            if(errors==0){SessionState.SetInt(Key+".result",0);Debug.Log("Map14 original entity transform views Play Mode passed: parent transforms, source Z/center/offset, flip magnitudes, grid move/event order, body-range/query forwarding, controller reuse and attachment registry replacement. Shared inputs are isolated; formal entity prefab/map/input/save/Player remain pending.");}EditorApplication.isPlaying=false;
        }
